/// The tool-description surface: `surfaces/coder/tool-descriptions.v1.json`.
pub mod tool_descriptions {
    /// `rust.read`
    pub const RUST_READ: &str = "Read a file and return its whole contents as text. `path` is relative to the session's working directory, or an absolute path inside it; a path that resolves outside it is refused. Use this rather than `cat` through the shell — there is nothing to quote and nothing to escape.";
    /// `rust.write`
    pub const RUST_WRITE: &str = "Write `content` to `path`, creating parent directories and replacing any file already there. The file is staged beside its destination and renamed into place, so nothing else on this machine can read it half-written. Use this rather than a shell heredoc. To change part of a file use `edit` instead: it does not ask you to reproduce the rest.";
    /// `rust.edit`
    pub const RUST_EDIT: &str = "Replace one exact run of text in a file. `oldText` must appear exactly once: if it appears more than once the edit is refused and the file is left alone, so add the lines above and below the one you mean until the match is unique, then call again. Several replacements on one file can be sent as `edits: [{oldText, newText}, ...]`; they apply in order, all land or none do, and the call prices as one against the turn budget. `oldText`/`newText` are not used when `edits` is present. Match byte for byte first; if nothing matches exactly, the site is still found when the difference is only trailing or leading whitespace, or doubled backslashes before a newline, and whole lines are replaced -- but a miss is cheaper than a misspelled guess, so copy the text rather than retyping it. On a miss the reply shows the file's real lines beside what you sent. `newText` may be empty to delete the run. Use this rather than `sed` for a surgical change.";
    /// `rust.bash`
    pub const RUST_BASH: &str = "Run a command through `/bin/sh -c` in the session's working directory, {cwd}. Returns combined stdout and stderr, and reports a non-zero exit as a failure rather than as ordinary output. Batch independent commands into one call with `&&` instead of one call each: every call replays the conversation so far. For git, survey with `--stat` or `--name-only` before `-p`; a full patch in the transcript is re-sent every later round. This is the same runner as `shell`, and either name reaches it.";
    /// `rust.shell`
    pub const RUST_SHELL: &str = "Run a shell command on this machine. The working directory is {cwd}, so paths are relative to it and you do not need to ask where you are. Returns combined stdout and stderr with the exit code. Batch independent commands into one call with && instead of one call each: every call replays the conversation so far. For git, survey with `--stat` or `--name-only` before `-p`; a full patch in the transcript is re-sent every later round.";
    /// `rust.skill`
    pub const RUST_SKILL: &str = "Read one of this repository skill procedures: a written procedure with conventions, commands, and rules. Call it before doing work a skill covers. Skills available:{skills}";
    /// `rust.openagents`
    pub const RUST_OPENAGENTS: &str = "Run the OpenAgents CLI commands (issue, project, repo, auth, etc.). Pass the arguments as a list without openagents itself.";
    /// `rust.delegate`
    pub const RUST_DELEGATE: &str = "Run one self-contained task through a delegated coding agent. Set `agent` to `coder-mini` for a fresh in-process Coder with `read-only` tools by default (inherits this session's model), `explore` for a read-only investigator on `gemini-3.7-flash`, `plan` for a read-only planner on `glm-5.3-flash`, or `coder` for a fixed read-write agent. Coder Mini also accepts `tools` as `read-only`, `read-write`, or `all`. Built-in agents accept `model` as a catalog id resolved like `--model`, overriding the agent's default, and `isolation` as `worktree` on a read-write run (unchanged worktrees are removed; changed ones are kept). A cwd override is not accepted yet and cannot be combined with isolation. No built-in agent can delegate again. Omit `agent` to keep fan-out: independent children run the same prompt on {lane}, up to {max_count}. Pass `lane` to pick a child harness for this call (`openagents`, `gemini`, `opencode/<model>`, `devin`, `claude`, `codex`). Pass `worktree` as `isolated` for a fresh git worktree per child; omit it or pass `none` to share this session's directory. `model`, `command`, `config`, and `ask` override this session's `--child-*` flags for this call only. Use `description` for an optional 3–5 word tool-call label. Every delegated agent starts with no context from this conversation and cannot ask questions, so the prompt must name the files, commands, constraints, and report. Prefer `shell` for one command; use an agent for work worth a separate coding session.{external}";
    /// `rust.capability`
    pub const RUST_CAPABILITY: &str = "Discover and load installed plugin capabilities: sandboxed, digest-pinned WebAssembly programs this machine already holds for common agent work. Before writing a script for a task, search here first — a capability that covers it is bounded, reviewable, and returns structured output. Call with `query` describing what you need to get the best matches; then call again with `name` set to the exact returned name to load it and make its dedicated tool available. Every later call to the loaded capability uses that exact name as the tool name.";
    /// `goal`
    pub const GOAL: &str = "Report a state change on the active persistent task goal for this session. The goal's objective, status, and budget already accompany each turn; call this with action='complete' when the goal is done and verified, or 'block'/'pause'/'resume' to update its status.";
    /// `rust.checkpoint`
    pub const RUST_CHECKPOINT: &str = "Record one milestone note for this session: which issue or task, what landed (files, commits, test results), what is unfinished or broken, and the exact next step. A few sentences. Write one at every natural milestone -- an issue implemented and green, a blocker hit and worked around, a switch to different work -- and always before the turn's tool budget runs low. The note is shown to whoever resumes this session, including a future session after this one dies; it is the difference between picking up the work and excavating it.";
    /// `history_recall`
    pub const HISTORY_RECALL: &str = "Answer a question about this session's own past: what a command printed, what a turn decided, when something happened. Zero model calls, reads the session record owner-locally. The question is one of Grep (find text in past output - use this to recover failure names instead of re-running anything), CursorSlice (records between two sequence numbers), TimeSlice (records between two ISO instants), KeyTurns (first N turns, one span each), or TurnSummary (counts, tools, and text of one turn; its turnId is the sequence number of the turn's first record). Caps bound the answer and a cap hit is reported in the honesty field - `partial_budget` means read more or narrow the question, not that the answer is wrong. The answer cites the exact records it came from.";
    /// `rust.swarm_list`
    pub const RUST_SWARM_LIST: &str = "List the other Coder sessions on this machine: id, role, lane, cwd, live or stale. Optional `cwd` keeps sessions in that directory; optional `tree` is a parent session id and keeps that session and its children. Costs nothing against the hourly swarm-send budget. An empty machine returns an empty list. Refuses only when `tree` names a session that is not registered.";
    /// `rust.swarm_send`
    pub const RUST_SWARM_SEND: &str = "Deliver one message to another session on this machine. `to` is a session id, `role:children-of:<id>`, or `all`. `body` is the text. `kind` is question, answer, status, handoff, or broadcast (default status). `reply_expected` asks the recipient to spend a turn answering. Optional `thread` continues a chain. Costs one from this session's hourly send budget (60/hour). Refuses: an empty body, a self-send, an unknown kind, a body over 256 KiB, an unregistered or stale destination, a sender that has spent the hourly budget, and a reply-expected chain deeper than the cap (default 2; the refusal names the cap). A muted neighbor is still deliverable; mute only silences what this session reads.";
    /// `rust.swarm_inbox`
    pub const RUST_SWARM_INBOX: &str = "Read this session's swarm inbox. `drain` true (the default) stamps the returned messages read, up to eight per call; the rest stay unread for the next turn and are never dropped. `drain` false is a peek. Costs nothing against the send budget. Refuses a gapped inbox (a missing sequence is a lost message). Muted senders are omitted and stay unread. Messages arrive as tool results, never as user speech.";
}

